<script setup>
import { computed, ref } from 'vue'
import { useMainFlow } from './useMainFlow.js'
import { dateTime, movement, number } from './model.js'
import PrototypeChart from './PrototypeChart.vue'
const emit=defineEmits(['select'])
const flow=useMainFlow(),daily=flow.daily,stock=flow.stock
const query=ref(''),side=ref('in')
const developer=new URLSearchParams(location.search).get('developer')==='1'
const cash=v=>v==null?'—':(v>0?'+':'')+number(v/1e8)+'亿'
const ordered=computed(()=>[...(daily.value?.industries||[])].sort((a,b)=>side.value==='in'?b.main-a.main:a.main-b.main))
const leaders=computed(()=>[...(daily.value?.stocks||[])].sort((a,b)=>side.value==='in'?b.main-a.main:a.main-b.main).slice(0,8))
const rankChart=computed(()=>({kind:'flow_rank',title:'行业大单与特大单净买额，盘后日频',x:ordered.value.slice(0,8).map(g=>g.name),series:[{name:'大额单净买额（亿）',data:ordered.value.slice(0,8).map(g=>g.main/1e8)}]}))
const curve=computed(()=>({kind:'main_flow',title:'腾讯估算主力累计净额，单位亿元',chart_type:'line',x:stock.value?.points.map(p=>p.at.slice(11,16))||[],series:[{name:'主力累计净额（亿）',axis:0,data:stock.value?.points.map(p=>p.main/1e8)||[]},{name:'超大单累计净额（亿）',axis:0,data:stock.value?.points.map(p=>p.extra/1e8)||[]},{name:'大单累计净额（亿）',axis:0,data:stock.value?.points.map(p=>p.large/1e8)||[]}]}))
const priceCurve=computed(()=>({kind:'flow_price',title:'同一资金数据源的分钟价格（元）',chart_type:'line',x:stock.value?.points.map(p=>p.at.slice(11,16))||[],series:[{name:'分钟价格（元）',axis:0,data:stock.value?.points.map(p=>p.price)||[]}]}))
const stateText=computed(()=>stock.value?.refresh_error?'刷新异常，保留原快照':stock.value?.freshness==='LIVE'?'盘中分钟数据 · 30秒刷新':stock.value?.freshness==='DELAYED'?'分钟数据延迟':'最近交易分钟 · 30秒刷新')
const divergence=key=>key==='PRICE_UP_FLOW_OUT'?'价格上涨 · 主力净流出':key==='PRICE_DOWN_FLOW_IN'?'价格下跌 · 主力净流入':key?'价格与资金未见上述背离':'连续分钟不足'
</script>
<template>
  <section class="workspace-section main-flow-monitor" aria-label="主力资金监控">
    <div class="section-heading"><div><h2>主力资金监控</h2><p class="condition-note">观察大额订单资金动向，不能据此识别具体机构。</p></div></div>
    <div class="panel flow-live">
      <div class="flow-heading"><h3>个股盘中主力</h3><form class="flow-search" @submit.prevent="flow.search(query)"><input v-model="query" aria-label="资金监控股票" placeholder="输入任意沪深股票名称或代码" autocomplete="off"><button class="btn" :disabled="flow.searching.value||!query.trim()">{{ flow.searching.value?'查找中…':'查看资金' }}</button></form><button class="btn" :disabled="flow.loading.value||!flow.symbol.value" @click="flow.refreshStock()">{{ flow.loading.value?'刷新中…':'刷新' }}</button></div>
      <p v-if="flow.searchError.value" class="error-text" role="alert">{{ flow.searchError.value }}</p><div v-if="flow.matches.value.length" class="flow-matches"><button v-for="item in flow.matches.value" :key="item.symbol" class="chip" @click="flow.select(item.symbol)">{{ item.name }} {{ item.code }}</button></div>
      <p v-if="flow.stockError.value||stock?.refresh_error" class="notice error-text" role="alert">{{ flow.stockError.value||stock.refresh_error }}</p>
      <template v-if="stock">
        <div class="flow-stock-heading"><strong>{{ stock.name }} <small class="muted">{{ stock.code }} · {{ stock.industry }}</small></strong><span class="condition-note">{{ stateText }} · 截至 {{ dateTime(stock.asof) }}</span><button class="chip" @click="emit('select',{name:stock.name,code:stock.code})">研究此股</button></div>
        <div class="flow-kpis"><div><span>当日主力累计净额</span><strong class="num" :class="movement(stock.latest.main)">{{ cash(stock.latest.main) }}</strong></div><div><span>超大单 / 大单净额</span><strong class="num"><b :class="movement(stock.latest.extra)">{{ cash(stock.latest.extra) }}</b> / <b :class="movement(stock.latest.large)">{{ cash(stock.latest.large) }}</b></strong></div><div v-for="w in stock.windows" :key="w.minutes"><span>截至该分钟 · 近{{ w.minutes }}分钟增量</span><strong class="num" :class="movement(w.main)">{{ cash(w.main) }}</strong><small>{{ divergence(w.divergence) }}</small></div></div>
        <div class="flow-curves"><PrototypeChart :block="curve" :height="230"/><PrototypeChart :block="priceCurve" :height="230"/></div>
        <p class="condition-note">腾讯证券估算口径：主力＝超大单＋大单。曲线是当日累计值；近5／15分钟是累计值之差。午休或缺点不补造连续窗口。</p>
      </template>
      <p v-else class="flow-wait" role="status">{{ flow.loading.value?'正在读取真实分钟资金…':flow.dailyLoading.value?'正在读取资金榜，随后打开代表股分钟监控…':'输入股票，查看主力资金分钟曲线。' }}</p>
    </div>
    <div class="panel flow-daily">
      <div class="flow-heading"><div><h3>行业与个股资金榜 <span class="tag">盘后日频</span></h3><p class="condition-note">{{ daily?daily.session+' · Tushare · '+daily.coverage.industries+'个行业 / '+daily.coverage.stocks+'只股票':'正在读取最新完整盘后数据' }} · 与上方腾讯口径分别展示</p></div><div class="flow-options" role="group" aria-label="资金榜排序"><button class="chip" :aria-pressed="side==='in'" @click="side='in'">净额从高到低</button><button class="chip" :aria-pressed="side==='out'" @click="side='out'">净额从低到高</button><button class="btn" :disabled="flow.dailyLoading.value" @click="flow.refreshDaily()">{{ flow.dailyLoading.value?'读取中…':'更新盘后榜' }}</button></div></div>
      <p v-if="flow.dailyError.value||daily?.refresh_error" class="notice error-text" role="alert">{{ flow.dailyError.value||daily.refresh_error }}</p>
      <div v-if="daily" class="flow-daily-grid"><div><PrototypeChart :block="rankChart" :height="250"/><details class="flow-all-industries"><summary>查看全部 {{ ordered.length }} 个行业</summary><div v-for="g in ordered" :key="g.id" class="flow-industry"><strong>{{ g.name }} <small>{{ g.count }}只</small></strong><b class="num" :class="movement(g.main)">{{ cash(g.main) }}</b><span>净买入 {{ g.inflow_count }} / 净卖出 {{ g.outflow_count }}</span></div></details></div><div class="flow-stock-rank"><div class="flow-rank-head"><span>点击股票查看分钟资金</span><span>大额单净买额</span></div><button v-for="(q,i) in leaders" :key="q.symbol" class="flow-stock-row" :class="{'is-selected':flow.symbol.value===q.symbol}" @click="flow.select(q.symbol)"><span class="muted num">{{ i+1 }}</span><span>{{ q.name }} <small>{{ q.code }} · {{ q.industry }}</small></span><strong class="num" :class="movement(q.main)">{{ cash(q.main) }}</strong></button></div></div>
      <p v-else class="flow-wait" role="status">{{ flow.dailyLoading.value?'正在读取官方交易日、完整行业成分与资金数据…':'盘后资金尚未取得，请更新重试。' }}</p>
      <details class="flow-method"><summary>资金口径与数据时间</summary><p>盘后榜使用 Tushare 大单、特大单买入减卖出，万元换算为元后按申万一级行业完整成员汇总；不是将总净流入字段直接叫作主力资金。行业榜尚未接入全市场盘中资金汇总。不同供应商阈值和统计方式不同，金额不做一致性认定。</p><p v-if="daily">盘后数据日期 {{ daily.session }}；读取 {{ dateTime(daily.retrieved_at) }}。</p><p v-if="stock">分钟数据截至 {{ dateTime(stock.asof) }}；读取 {{ dateTime(stock.retrieved_at) }}。公开互联网接口可能延迟或断连，异常保留原数据并提示。</p><pre v-if="developer">{{ JSON.stringify({daily:daily?.sources,stock:stock?.sources},null,2) }}</pre></details>
    </div>
  </section>
</template>
<style scoped>
.main-flow-monitor h2{margin:0}.main-flow-monitor h3{font-size:14px;margin:0}.main-flow-monitor p{margin:6px 0}.flow-live,.flow-daily{min-width:0;padding:16px 18px;margin-bottom:12px}.flow-heading,.flow-stock-heading{display:flex;align-items:center;gap:12px;flex-wrap:wrap;justify-content:space-between}.flow-search{display:flex;gap:8px;margin-left:auto}.flow-search input{width:250px;background:var(--bg-raised);border:1px solid var(--border);border-radius:4px;padding:7px 10px;color:var(--text-1);font:inherit;font-size:12px}.flow-stock-heading{justify-content:flex-start;margin:14px 0 10px}.flow-stock-heading>strong{font-size:15px}.flow-stock-heading small{font-size:11px;font-weight:400}.flow-stock-heading .chip{margin-left:auto}.flow-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;padding:12px 0;border-top:1px solid var(--border);border-bottom:1px solid var(--border)}.flow-kpis>div{display:flex;flex-direction:column;gap:6px}.flow-kpis span,.flow-kpis small{color:var(--text-3);font-size:11px}.flow-kpis strong{font-size:20px}.flow-kpis b{font-weight:500;font-size:14px}.flow-curves{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);gap:12px;margin-top:12px}.flow-curves>*,.flow-daily-grid>*{min-width:0}.flow-daily-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px;margin-top:12px}.flow-options,.flow-matches{display:flex;gap:6px;flex-wrap:wrap}.flow-options [aria-pressed=true]{color:var(--accent);border-color:var(--accent)}.flow-rank-head{display:flex;justify-content:space-between;font-size:11px;color:var(--text-3);padding:8px 0}.flow-stock-row{display:grid;grid-template-columns:18px 1fr 100px;gap:6px;align-items:center;width:100%;background:transparent;border:0;border-bottom:1px solid var(--border);padding:9px 5px;text-align:left;color:var(--text-1);cursor:pointer;font:inherit;font-size:12px}.flow-stock-row strong{text-align:right}.flow-stock-row small{display:block;color:var(--text-3);font-size:10px;margin-top:4px}.flow-stock-row:hover,.flow-stock-row.is-selected{background:var(--bg-raised)}.flow-all-industries,.flow-method{color:var(--text-3);font-size:11px;line-height:1.8;margin-top:12px}.flow-all-industries summary,.flow-method summary{cursor:pointer}.flow-industry{display:grid;grid-template-columns:1fr 100px 1fr;gap:8px;padding:7px 0;border-bottom:1px solid var(--border)}.flow-industry small{font-weight:400;margin-left:6px}.flow-industry b{text-align:right}.flow-industry span{text-align:right}.flow-method pre{max-height:200px;overflow:auto}.flow-wait{padding:25px 0;color:var(--text-3);font-size:12px}.main-flow-monitor :is(button,input,summary):focus-visible{outline:2px solid var(--accent);outline-offset:3px}@media(max-width:850px){.flow-curves,.flow-daily-grid{grid-template-columns:minmax(0,1fr)}.flow-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.flow-search{margin-left:0}.flow-stock-heading .chip{margin-left:0}}@media(max-width:500px){.flow-live,.flow-daily{min-width:0;padding:14px 12px}.flow-search{width:100%}.flow-search input{min-width:0;width:auto;flex:1}.flow-kpis strong{font-size:18px}.flow-kpis b{font-size:12px}.flow-industry{grid-template-columns:1fr 100px}.flow-industry span{grid-column:1/-1}.flow-options{margin-top:6px}}
</style>
